#!/usr/bin/env python3
"""Generate the machine's 257-point, Q15 Hann window. No runtime math library."""
import math
from pathlib import Path

values = [round((0.5 - 0.5 * math.cos(2 * math.pi * i / 256)) * 32767) for i in range(257)]
rows = [', '.join(map(str, values[i:i + 12])) for i in range(0, len(values), 12)]
(Path(__file__).resolve().parents[1] / 'window.h').write_text(
    '// Generated by tools/generate_window.py.\n#pragma once\n'
    'namespace granular {\nstatic const opxy::i16 hann[257] = {\n    '
    + ',\n    '.join(rows) + '\n};\n}\n')
